        "withdraw.account_number": "\u2116 \u0441\u0447\u0451\u0442\u0430",
        "withdraw.issue_date": "\u0414\u0430\u0442\u0430 \u0437\u0430\u044f\u0432\u043a\u0438",
        "withdraw.error": "\u041f\u0440\u043e\u0438\u0437\u043e\u0448\u043b\u0430 \u043e\u0448\u0438\u0431\u043a\u0430! \u041f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u043f\u043e\u0437\u0436\u0435!",
        "withdraw.trading": "\u0422\u043e\u0440\u0433\u043e\u0432\u044b\u0439 \u0441\u0447\u0451\u0442",
        "withdraw.withdraw_password_error": "\u041f\u0430\u0440\u043e\u043b\u044c \u0443\u043a\u0430\u0437\u0430\u043d \u043d\u0435\u0432\u0435\u0440\u043d\u043e",
        "withdraw.opex_instruction": "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043d\u044b\u0439 \u043d\u043e\u043c\u0435\u0440 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430, \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u0443\u044e \u0441\u0443\u043c\u043c\u0443 \u0438 \u043f\u0430\u0440\u043e\u043b\u044c \u0442\u043e\u0440\u0433\u043e\u0432\u043e\u0433\u043e \u0441\u0447\u0435\u0442\u0430.",
        "withdraw.opex_instruction_link": "\u041f\u043e\u0434\u0440\u043e\u0431\u043d\u044b\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u0438",
        "withdraw.alert_text": '\u0423\u0432\u0430\u0436\u0430\u0435\u043c\u044b\u0435 \u0422\u0440\u0435\u0439\u0434\u0435\u0440\u044b!<br />\u0421 06.12.2022 \u0433\u043e\u0434\u0430 \u043d\u0430 \u0441\u0430\u0439\u0442\u0435 <a href="/">www.buleto.com</a>, \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 \xab\u0412\u044b\u0432\u0435\u0441\u0442\u0438\xbb \u0441\u0430\u043c\u043e\u0441\u0442\u043e\u044f\u0442\u0435\u043b\u044c\u043d\u043e \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c \u0437\u0430\u044f\u0432\u043a\u0443 \u043d\u0430 \u0432\u044b\u0432\u043e\u0434 \u0434\u0435\u043d\u0435\u0436\u043d\u044b\u0445 \u0441\u0440\u0435\u0434\u0441\u0442\u0432 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u043d\u0435 \u0431\u043e\u043b\u0435\u0435  3-\u0445 \u0440\u0430\u0437 \u0432 \u0441\u0443\u0442\u043a\u0438.',
        "withdraw.alert_2": '\u0423\u0440\u043c\u0430\u0442\u0442\u0443\u0443 \u043a\u043e\u043d\u043e\u043a\u0442\u043e\u0440! <br />\u0416\u0430\u04a3\u044b \u0436\u044b\u043b\u0434\u044b\u043a \u043c\u0430\u0439\u0440\u0430\u043c\u0434\u0430\u0440\u0433\u0430 \u043a\u0430\u0440\u0430\u0442\u0430 \u0441\u043e\u043e\u0434\u0430 \u0430\u044f\u043d\u0442\u0442\u0430\u0440\u044b\u043d\u0434\u0430 \u0438\u0448 \u0441\u0430\u0430\u0442\u0442\u0430\u0440\u044b<br />\u0423\u0432\u0430\u0436\u0430\u0435\u043c\u044b\u0435 \u0433\u043e\u0441\u0442\u0438!<br />\u0420\u0435\u0436\u0438\u043c \u0440\u0430\u0431\u043e\u0442\u044b \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u0437\u0430\u043b\u043e\u0432 \u043d\u0430 \u041d\u043e\u0432\u043e\u0433\u043e\u0434\u043d\u0438\u0435 \u043f\u0440\u0430\u0437\u0434\u043d\u0438\u043a\u0438<br /><br /> 31.12.2022 \u0434\u043e 18:00 \u0447\u0435\u0439\u0438\u043d<br /> 01.01.2023 \u0441 17:00 \u0431\u0430\u0448\u0442\u0430\u043f<br /><br /><a href="/traderoom">BULETO</a>',
        "withdraw.alert_verification": '\u0412\u043d\u0438\u043c\u0430\u043d\u0438\u0435: \u0421 1 \u0444\u0435\u0432\u0440\u0430\u043b\u044f \u0441 13:00 \u0447\u0430\u0441\u043e\u0432 <br /> \u0412\u0430\u043c \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e \u043f\u0440\u043e\u0439\u0442\u0438 \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044e \u0432 \u0446\u0435\u043b\u044f\u0445 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0439 \u0437\u0430\u043a\u043e\u043d\u043e\u0434\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u041a\u044b\u0440\u0433\u044b\u0437\u0441\u043a\u043e\u0439 \u0420\u0435\u0441\u043f\u0443\u0431\u043b\u0438\u043a\u0438 \u0432 \u0441\u0444\u0435\u0440\u0435 \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u0444\u0438\u043d\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044e \u0442\u0435\u0440\u0440\u043e\u0440\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0438 \u043b\u0435\u0433\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 (\u043e\u0442\u043c\u044b\u0432\u0430\u043d\u0438\u044e) \u043f\u0440\u0435\u0441\u0442\u0443\u043f\u043d\u044b\u0445 \u0434\u043e\u0445\u043e\u0434\u043e\u0432. <br /><br /> \u0417\u0410\u041a\u041e\u041d \u041a\u042b\u0420\u0413\u042b\u0417\u0421\u041a\u041e\u0419 \u0420\u0415\u0421\u041f\u0423\u0411\u041b\u0418\u041a\u0418 <br /> \u043e\u0442 6 \u0430\u0432\u0433\u0443\u0441\u0442\u0430 2018 \u0433\u043e\u0434\u0430 \u2116 87 <br /> \u041e \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0438 \u0444\u0438\u043d\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044e \u0442\u0435\u0440\u0440\u043e\u0440\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0438 \u043b\u0435\u0433\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 (\u043e\u0442\u043c\u044b\u0432\u0430\u043d\u0438\u044e) \u043f\u0440\u0435\u0441\u0442\u0443\u043f\u043d\u044b\u0445 \u0434\u043e\u0445\u043e\u0434\u043e\u0432 <br /><br /> \u041f\u043e\u0436\u0430\u043b\u0443\u0439\u0441\u0442\u0430, \u043f\u0440\u043e\u0439\u0434\u0438\u0442\u0435 \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044e \u0438 \u0432\u044b\u0432\u043e\u0434 \u0441\u0440\u0435\u0434\u0441\u0442\u0432 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0431\u0443\u0434\u0435\u0442 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d. <br /> \u0412\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044e \u0441\u043c\u043e\u0436\u0435\u0442\u0435 \u043f\u0440\u043e\u0439\u0442\u0438 \u043f\u043e \u043d\u043e\u043c\u0435\u0440\u0443 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430 <a href="https://wa.me/+19292141229">+19292141229</a> (WhatsApp) \u0438\u043b\u0438 \u0432 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u0437\u0430\u043b\u0430\u0445 <a href="/locations">\u201cBuleto\u201d</a>',
        "withdraw.select_withdrawal": "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043f\u043e\u0441\u043e\u0431 \u0432\u044b\u0432\u043e\u0434\u0430",
