        "deposit.methods.text": "\u60a8\u53ef\u4ee5\u5728\u201cBuleto\u201d\u7684\u4efb\u4f55\u4f4d\u4e8e\u6bd4\u4ec0\u51ef\u514b\u7684\u7ecf\u7eaa\u4eba\u4ff1\u4e50\u90e8\u4e0d\u53d7\u624b\u7eed\u8d39\u7eed\u4ea4\u4ea4\u6613\u8d26\u6237",
        "deposit.methods.address_list": "<li class='dot'>\u695a\u4f0a\u5927\u8857 52/3\u53f7 <span>(\u5361\u5c14\u5e73\u65af\u514b\u8857\u4ea4\u53c9)</span></li> <li class='dot'>\u963f\u6b65\u675c\u62c9\u5408\u66fc\u8bfa\u592b\u8857 182\u53f7 <span>(\u82cf\u7ef4\u57c3\u8857 x \u57fa\u8f85\u8857)</span></li> <li class='dot'>\u5df4\u4f0a\u7279\u514b\u82f1\u96c4\u8857 55\u53f7 <span>(\u82cf\u7ef4\u57c3\u8857 x \u9ad8\u5c14\u57fa\u8857)</span></span></li> <li class='dot'>\u548c\u5e73\u5927\u8857 35\u53f7 <span>(\u827e\u5c3c\u8857\u4ea4\u53c9)</span></li> <li class='dot'>\u963f\u5b8f\u767d\u8036\u592b\u8857 116a\u53f7 <span>(\u6258\u514b\u6258\u7eb3\u91cc\u8036\u592b\u8857)</span></span></li> <li class='dot'>\u4e1d\u7ef8\u4e4b\u8def\u5927\u8857183\u53f7 <span>(\u5e03\u743c\u5c3c\u8857\u4ea4\u53c9)</span></li>",
        "deposit.modal.deposit": "\u7eed\u4ea4\u8d26\u6237",
        "deposit.modal.trial_account": "\u6559\u5b66\u7684\u8d26\u6237",
        "deposit.modal.text_1": "\u53ef\u4ee5\u7eed\u4ea4\u6559\u5b66\u7684\u8d26\u6237<br/>\uff0c \u5982\u60a8\u4f59\u989d<br/> \u5c11\u4e8e10,000.00\u7d22\u59c6",
        "deposit.modal.replenish": "\u7eed\u4ea4",
        "deposit.modal.from": "\u4ece",
        "deposit.modal.to": "\u5230",
        "deposit.modal.real_account": "\u5b9e\u8d26\u53f7",
        "deposit.modal.text_2": "\u901a\u8fc7\u81ea\u52a8\u5145\u503c\u673a\u3001\u624b\u673a\u548c\u7f51\u4e0a\u94f6\u884c\u3001 <br/> \u7535\u5b50\u94b1\u5305\u7eed\u4ea4\u4f59\u989d\u65f6\uff0c\u8bf7\u4f7f\u7528\u60a8\u7684\u5e10\u53f7443725",
        "deposit.kbk.name": "\u5409\u5c14\u5409\u65af\u65af\u5766\u201d\u94f6\u884c\u7684\u7f51\u4e0a\u94f6\u884c\u670d\u52a1",
        "deposit.kbk.amount": "\u624b\u7eed\u8d39",
        "deposit.kbk.text": "\u5982\u679c\u60a8\u662f\u5409\u5c14\u5409\u65af\u65af\u5766\u5546\u4e1a\u94f6\u884c\u7684\u5ba2\u6237\uff0c\u60a8\u53ef\u4ee5\u4f7f\u7528\u8be5\u7f51\u7ad9\u6216\u79fb\u52a8\u5e94\u7528\u7a0b\u5e8f\u7eed\u4ea4\u201cBuleto\u201d\u7684\u5e10\u6237\u800c\u65e0\u9700\u4efb\u4f55\u624b\u7eed\u8d39\uff01<br/>\u4e3a\u6b64\uff0c\u8bf7\u8f6c\u81f3\u201c\u4ea4\u6613 - \u5b9a\u671f\u4ed8\u6b3e - \u91d1\u878d\u670d\u52a1 - Buleto\u201d\u90e8\u5206\u3002 \u7136\u540e\u8f93\u5165\u60a8\u7684\u5e10\u53f7 <b>{accountNumber}<b>\uff0c\u4ed8\u6b3e\u91d1\u989d\uff0c\u7136\u540e\u70b9\u51fb\u201c\u7ee7\u7eed\u201d\u3002 <br/>\u5173\u4e8e\u5409\u5c14\u5409\u65af\u65af\u5766\u5546\u4e1a\u94f6\u884c\u7684\u4e92\u8054\u7f51\u548c\u624b\u673a\u94f6\u884c\u7684\u66f4\u591a\u4fe1\u606f\uff0c\u8bf7\u53c2\u9605<a href='http://www.cbk.kg/'> cbk.kg </a>",
        "deposit.mobilnik.name": "\u7535\u5b50\u94b1\u5305\u201c\u624b\u673a\u94b1\u201d",
        "deposit.mobilnik.amount": "\u624b\u7eed\u8d39",
        "deposit.mobilnik.text": "\u4f7f\u7528\u201c\u624b\u673a\u94b1\u201d\u7f51\u7ad9\u6216\u79fb\u52a8\u5e94\u7528\u7a0b\u5e8f\u7eed\u4ea4\u201cBuleto\u201d\u8d26\u6237\u800c\u65e0\u9700\u4efb\u4f55\u624b\u7eed\u8d39\uff01 <br/>\u4e3a\u6b64\uff0c\u8bf7\u8f6c\u5230\u201c\u7535\u5b50\u94b1\u5305 - \u5176\u4ed6\u670d\u52a1 - Buleto\u201d\u90e8\u5206\u3002 \u7136\u540e\u8f93\u5165\u60a8\u7684\u5e10\u53f7 <b>{accountNumber}<b>\uff0c\u4ed8\u6b3e\u91d1\u989d\u5e76\u70b9\u51fb\u201c\u652f\u4ed8\u201d\u3002<br/>  \u5728\u201c\u624b\u673a\u94b1\u201d\u652f\u4ed8\u670d\u52a1\u7684\u5e2e\u52a9\u4e0b\uff0c\u60a8\u53ef\u4ee5\u652f\u4ed8\u5176\u4ed6\u670d\u52a1\uff0c\u5c06\u8d44\u91d1\u63d0\u53d6\u5230\u94f6\u884c\u8d26\u6237\u5e76\u5151\u73b0\u3002\u5173\u4e8e \u201c\u624b\u673a\u94b1\u201d\u7535\u5b50\u94b1\u5305\u7684\u66f4\u591a\u4fe1\u606f\uff0c\u8bf7\u53c2\u9605<a href='https://www.mobilnik.kg/'> mobilnik.kg </a>",
        "deposit.unipay.name": "\u652f\u4ed8\u7d42\u7aef\u201cUnipay\u201d",
        "deposit.unipay.amount": "\u4f63\u91d1 \u2014 2%",
        "deposit.unipay.text": "\u5728\u7d42\u7aef\u7684\u4e3b\u5c4f\u5e55\u4e0a\uff0c\u9078\u64c7\u201cBuleto\u201d\uff0c\u7136\u5f8c\u9078\u64c7\u201c\u5b58\u6b3e\u8cec\u6236\u201d\u3002 \u63a5\u4e0b\u4f86\uff0c\u8f38\u5165\u60a8\u7684\u5e33\u865f <b>{accountNumber}</b>\uff0c\u8f38\u5165\u6240\u9700\u91d1\u984d\uff0c\u7136\u5f8c\u9ede\u64ca\u201c\u652f\u4ed8\u201d\u3002",
        "deposit.onoi.name": "\u652f\u4ed8\u7d42\u7aef \xab\u041e\u04a3\u043e\u0439\xbb",
        "deposit.onoi.text": "\u5728\u7d42\u7aef\u7684\u4e3b\u5c4f\u5e55\u4e0a\uff0c\u9078\u64c7\u201c\u9280\u884c\u548c\u91d1\u878d\u670d\u52d9\u201d\u90e8\u5206\uff0c\u7136\u5f8c\u9078\u64c7\u201cBuleto\u201d\u3002 \u63a5\u4e0b\u4f86\uff0c\u8f38\u5165\u60a8\u7684\u5e33\u865f {accountNumber}\uff0c\u8f38\u5165\u4ed8\u6b3e\u91d1\u984d\u4e26\u9ede\u64ca\u201c\u652f\u4ed8\u201d\u3002",
        "deposit.mobilnik2.name": "\u624b\u673a\u201d\u81ea\u52a8\u5145\u503c\u673a",
        "deposit.mobilnik2.amount": "\u624b\u7eed\u8d39 \u2014 \u4ece10 \u7d22\u59c6 \u523050 \u7d22\u59c6, \u4f9d\u8d56\u4e8e\u91d1\u989d",
        "deposit.mobilnik2.text": "\u5728\u7d42\u7aef\u7684\u4e3b\u5c4f\u5e55\u4e0a\uff0c\u9078\u64c7\u201c\u9280\u884c\u548c\u91d1\u878d\u670d\u52d9 > \u7d93\u7d00\u670d\u52d9\u201d\u90e8\u5206\uff0c\u7136\u5f8c\u9078\u64c7\u201cBuleto\u201d\u3002 \u63a5\u4e0b\u4f86\uff0c\u8f38\u5165\u60a8\u7684\u5e33\u865f {accountNumber}\uff0c\u8f38\u5165\u4ed8\u6b3e\u91d1\u984d\u4e26\u9ede\u64ca\u201c\u652f\u4ed8\u201d",
        "deposit.o.name": "O\uff01\u94b1\u201d\u652f\u4ed8\u670d\u52a1",
        "deposit.o.amount": "\u624b\u7eed\u8d39=0\u7d22\u59c6",
        "deposit.o.text": "\u5982\u679c\u60a8\u662f\u201cO\uff01\u201d\u79fb\u52a8\u8fd0\u8425\u5546\u7684\u7528\u6237\uff0c\u60a8\u53ef\u4ee5\u7528\u624b\u673a\u7eed\u4ea4\u201cBuleto\u201d\u7684\u8d26\u6237\uff0c\u5e76\u4e0d\u53d7\u4efb\u4f55\u624b\u7eed\u8d39\uff01 <br/>\u4e3a\u6b64\uff0c\u8bf7\u5728\u201cO!\u94b1\u201d\u79fb\u52a8\u5e94\u7528\u7a0b\u5e8f\u4e2d\u8f6c\u5230\u201c\u4ed8\u8d39 - \u5176\u4ed6\u670d\u52a1 - Buleto\u201d\u90e8\u5206\u3002 \u7136\u540e\u8f93\u5165\u60a8\u7684\u5e10\u53f7{accountNumber}\uff0c\u4ed8\u6b3e\u91d1\u989d\u5e76\u70b9\u51fb\u201c\u652f\u4ed8\u201d\u3002 <br/>\u4e3a\u4e86\u66f4\u52a0\u65b9\u4fbf\uff0c\u4f60\u53ef\u4ee5\u7ed1\u5b9aVisa / MasterCard / World\u94f6\u884c\u5361\u4e0e\u201cO!\u94b1\u201d\u79fb\u52a8\u5e94\u7528\u7a0b\u5e8f\u3002 <br/>\u5173\u4e8e\u201cO!\u94b1\u201d\u79fb\u52a8\u5e94\u7528\u7a0b\u5e8f\u66f4\u591a\u4fe1\u606f\uff0c\u8bf7\u53c2\u9605<a href='https://dengi.kg'> dengi.kg </a>",
        "deposit.megacom.name": "\xabMegacom\xbb\u81ea\u52a8\u5145\u503c\u673a",
        "deposit.megacom.amount": "\u624b\u7eed\u8d39 \u2014 \u4ece10 \u7d22\u59c6 \u523050 \u7d22\u59c6, \u4f9d\u8d56\u4e8e\u91d1\u989d",
        "deposit.megacom.text": "\u5728\u81ea\u52a8\u5145\u503c\u673a\u4e3b\u5c4f\u5e55\u4e0a\uff0c\u9009\u62e9\u201c\u5176\u4ed6\u670d\u52a1\u201d\u90e8\u5206\uff0c\u7136\u540e\u9009\u62e9\u201cBuleto\u201d\u3002 \u7136\u540e\u8f93\u5165\u60a8\u7684\u5e10\u53f7 \uff0c\u8f93\u5165\u4ed8\u6b3e\u91d1\u989d\u5e76\u70b9\u51fb\u201c\u4ed8\u6b3e\u201d\u3002",
        "deposit.quickpay.name": "\xabQuickPay\xbb \u81ea\u52a8\u5145\u503c\u673a",
        "deposit.quickpay.amount": "\u624b\u7eed\u8d39 \u2014 \u4ece10 \u7d22\u59c6 \u523050 \u7d22\u59c6, \u4f9d\u8d56\u4e8e\u91d1\u989d",
        "deposit.quickpay.text": "\u5728\u81ea\u52a8\u5145\u503c\u673a\u4e3b\u5c4f\u5e55\u4e0a\uff0c\u9009\u62e9\u201c\u5176\u4ed6\u670d\u52a1\u201d\u90e8\u5206\uff0c\u7136\u540e\u9009\u62e9\u201cBuleto\u201d\u3002 \u7136\u540e\u8f93\u5165\u60a8\u7684\u5e10\u53f7<b> {accountNumber}</b>\uff0c\u8f93\u5165\u4ed8\u6b3e\u91d1\u989d\u5e76\u70b9\u51fb\u201c\u4ed8\u6b3e\u201d\u3002",
